"use client";

import { useId, type InputHTMLAttributes } from "react";

export type ComboboxOption = { value: string; label: string };
export function Combobox({ options, value, onValueChange, label = "Choose an option", className = "", ...props }: Omit<InputHTMLAttributes<HTMLInputElement>, "value" | "onChange" | "list"> & { options: ComboboxOption[]; value?: string; onValueChange?: (value: string) => void; label?: string }) { const id = useId(); return <><input role="combobox" aria-label={label} aria-autocomplete="list" list={id} value={value} onChange={(event) => onValueChange?.(event.target.value)} className={`co-h-10 co-w-full co-rounded-md co-border co-border-black/20 co-bg-white co-px-3 co-text-sm co-outline-none focus-visible:co-ring-2 ${className}`.trim()} {...props} /><datalist id={id}>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</datalist></>; }
